# Translate generated image descriptions (alt text) using DeepL API\nimport os\n\n# DeepL SDK for text translation\nfrom deepl import DeepL\n\nclass AltTextTranslate:\n    \"\"\"Translate an English alt text caption into another language.\n    \"\"\"\n    @staticmethod\n    def translate(english_text: str, target_lang: str = \"FR\") -> str:\n        \"\"\"Translate text to the target language using DeepL.\n        Args:\n            english_text (str): The original English caption.\n            target_lang (str): ISO language code of the destination language.\n        Returns:\n            str: Translated caption.\n        \"\"\"\n        # Create DeepL client – auth key is read from DEEPL_AUTH_KEY env var\n        translator = DeepL(auth_key=os.getenv(\"DEEPL_AUTH_KEY\"))\n        # Perform translation (English source automatically detected)\n        result = translator.translate_text(english_text, target_lang=target_lang)\n        return result.text.strip()\n\n# -----------------------------------------------------------------------------\n# End of alt_text_translate.py\n# -----------------------------------------------------------------------------
